    [TestMethod]
    public void GenerateSlug_SimpleTitle_ReturnsLowercaseSlug()
    {
        string result = _formatter.GenerateSlug("Hello World");

        Assert.AreEqual("hello-world", result);
    }

    [TestMethod]
    public void GenerateSlug_TitleWithMultipleWords_StartsWithFirstWord()
    {
        string result = _formatter.GenerateSlug("My Great Blog Post");

        StringAssert.StartsWith(result, "my-");
    }

    [TestMethod]
    public void GenerateSlug_TitleWithMultipleWords_EndsWithLastWord()
    {
        string result = _formatter.GenerateSlug("My Great Blog Post");

        StringAssert.EndsWith(result, "-post");
    }

    [TestMethod]
    public void GenerateSlug_TitleWithSpecialChars_DoesNotContainSpecialChars()
    {
        string result = _formatter.GenerateSlug("Hello! World? Yes.");

        StringAssert.Matches(result, new Regex(@"^[a-z0-9\-]+$"));
    }

    [TestMethod]
    public void GenerateSlug_TitleWithLeadingTrailingSpaces_TrimsResult()
    {
        string result = _formatter.GenerateSlug("  Padded Title  ");

        Assert.AreEqual("padded-title", result);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void GenerateSlug_WhitespaceInput_ThrowsArgumentException()
    {
        _formatter.GenerateSlug("   ");
    }

