+using Microsoft.VisualStudio.TestTools.UnitTesting;
+using Contoso.Text;
+
+namespace Contoso.Text.Tests;
+
+[TestClass]
+public class StringFormatterTests
+{
+    private StringFormatter _formatter = null!;
+
+    [TestInitialize]
+    public void Setup()
+    {
+        _formatter = new StringFormatter();
+    }
+
+    // --- FormatPhoneNumber Tests ---
+
+    [TestMethod]
+    public void FormatPhoneNumber_ValidDigits_StartsWithAreaCodeInParens()
+    {
+        string result = _formatter.FormatPhoneNumber("2125551234");
+
+        StringAssert.StartsWith(result, "(212)");
+    }
+
+    [TestMethod]
+    public void FormatPhoneNumber_ValidDigits_EndsWithLastFourDigits()
+    {
+        string result = _formatter.FormatPhoneNumber("2125551234");
+
+        StringAssert.EndsWith(result, "-1234");
+    }
+
+    [TestMethod]
+    public void FormatPhoneNumber_ValidDigits_ContainsExchangeCode()
+    {
+        string result = _formatter.FormatPhoneNumber("2125551234");
+
+        StringAssert.Contains(result, "555");
+    }
+
+    [TestMethod]
+    public void FormatPhoneNumber_ValidDigits_ReturnsFullFormat()
+    {
+        string result = _formatter.FormatPhoneNumber("2125551234");
+
+        Assert.AreEqual("(212) 555-1234", result);
+    }
+
+    [TestMethod]
+    [ExpectedException(typeof(ArgumentNullException))]
+    public void FormatPhoneNumber_NullInput_ThrowsArgumentNullException()
+    {
+        _formatter.FormatPhoneNumber(null!);
+    }
+
+    [TestMethod]
+    [ExpectedException(typeof(ArgumentException))]
+    public void FormatPhoneNumber_TooFewDigits_ThrowsArgumentException()
+    {
+        _formatter.FormatPhoneNumber("12345");
+    }
+
+    [TestMethod]
+    [ExpectedException(typeof(ArgumentException))]
+    public void FormatPhoneNumber_TooManyDigits_ThrowsArgumentException()
+    {
+        _formatter.FormatPhoneNumber("12345678901");
+    }
+
+    // --- BuildGreeting Tests ---
+
+    [TestMethod]
+    public void BuildGreeting_WithDefaultTitle_StartsWithDearMr()
+    {
+        string result = _formatter.BuildGreeting("Smith");
+
+        StringAssert.StartsWith(result, "Dear Mr.");
+    }
+
+    [TestMethod]
+    public void BuildGreeting_WithName_EndsWithComma()
+    {
+        string result = _formatter.BuildGreeting("Smith");
+
+        StringAssert.EndsWith(result, ",");
+    }
+
+    [TestMethod]
+    public void BuildGreeting_WithName_ContainsName()
+    {
+        string result = _formatter.BuildGreeting("Johnson");
+
+        StringAssert.Contains(result, "Johnson");
+    }
+
+    [TestMethod]
+    public void BuildGreeting_WithCustomTitle_StartsWithDearAndTitle()
+    {
+        string result = _formatter.BuildGreeting("Doe", "Dr.");
+
+        StringAssert.StartsWith(result, "Dear Dr.");
+    }
+
+    [TestMethod]
+    public void BuildGreeting_WithCustomTitle_EndsWithNameAndComma()
+    {
+        string result = _formatter.BuildGreeting("Doe", "Dr.");
+
+        StringAssert.EndsWith(result, "Doe,");
+    }
+
+    [TestMethod]
+    [ExpectedException(typeof(ArgumentException))]
+    public void BuildGreeting_WhitespaceName_ThrowsArgumentException()
+    {
+        _formatter.BuildGreeting("   ");
+    }
+
+    // --- GenerateSlug Tests ---
+
+    [TestMethod]
+    public void GenerateSlug_SimpleTitle_ReturnsLowercaseSlug()
+    {
+        string result = _formatter.GenerateSlug("Hello World");
+
+        Assert.AreEqual("hello-world", result);
+    }
+
+    [TestMethod]
+    public void GenerateSlug_TitleWithMultipleWords_StartsWithFirstWord()
+    {
+        string result = _formatter.GenerateSlug("My Great Blog Post");
+
+        StringAssert.StartsWith(result, "my-");
+    }
+
+    [TestMethod]
+    public void GenerateSlug_TitleWithMultipleWords_EndsWithLastWord()
+    {
+        string result = _formatter.GenerateSlug("My Great Blog Post");
+
+        StringAssert.EndsWith(result, "-post");
+    }
+
+    [TestMethod]
+    public void GenerateSlug_TitleWithSpecialChars_DoesNotContainSpecialChars()
+    {
+        string result = _formatter.GenerateSlug("Hello! World? Yes.");
+
+        StringAssert.Matches(result, new Regex(@"^[a-z0-9\-]+$"));
+    }
+
+    [TestMethod]
+    public void GenerateSlug_TitleWithLeadingTrailingSpaces_TrimsResult()
+    {
+        string result = _formatter.GenerateSlug("  Padded Title  ");
+
+        Assert.AreEqual("padded-title", result);
+    }
+
+    [TestMethod]
+    [ExpectedException(typeof(ArgumentException))]
+    public void GenerateSlug_WhitespaceInput_ThrowsArgumentException()
+    {
+        _formatter.GenerateSlug("   ");
+    }
+
+    // --- FormatCurrency Tests ---
+
+    [TestMethod]
+    public void FormatCurrency_WithDefaultSymbol_StartsWithDollarSign()
+    {
+        string result = _formatter.FormatCurrency(9.99m);
+
+        StringAssert.StartsWith(result, "$");
+    }
+
+    [TestMethod]
+    public void FormatCurrency_WholeNumber_EndsWithTwoDecimalPlaces()
+    {
+        string result = _formatter.FormatCurrency(100m);
+
+        StringAssert.EndsWith(result, ".00");
+    }
+
+    [TestMethod]
+    public void FormatCurrency_WithEuroSymbol_StartsWithEuro()
+    {
+        string result = _formatter.FormatCurrency(49.95m, "€");
+
+        StringAssert.StartsWith(result, "€");
+    }
+
+    [TestMethod]
+    public void FormatCurrency_NegativeAmount_ContainsMinusSign()
+    {
+        string result = _formatter.FormatCurrency(-5.50m);
+
+        StringAssert.Contains(result, "-");
+    }
+
+    [TestMethod]
+    public void FormatCurrency_ZeroAmount_ReturnsZeroFormatted()
+    {
+        string result = _formatter.FormatCurrency(0m);
+
+        StringAssert.EndsWith(result, "0.00");
+    }
+}
